import{c as t,Q as i,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Forget Without Compromise: Nexus Sampling for Streaming KV-Cache Eviction Under Fixed Budgets","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.23961","title":"Forget Without Compromise: Nexus Sampling for Streaming KV-Cache Eviction Under Fixed Budgets","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.23961,"authors":["Duc Duong","Hoang Anh Duy Le","Jianwen Xie","Anshumali Shrivastava","Zhaozhuo Xu"],"domains":["cs.LG","KV cache"],"html":"https://arxiv.org/html/2606.23961v1","pdf_path":"pdfs/2606.23961.pdf","published_date":"2026-06-22T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-22-nexus-sampling-streaming-kv-cache-eviction-2606-23961.md","filePath":"research/papers/2026-06-22-nexus-sampling-streaming-kv-cache-eviction-2606-23961.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-22-nexus-sampling-streaming-kv-cache-eviction-2606-23961.md"};function o(s,e,c,l,h,g){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="forget-without-compromise-nexus-sampling-for-streaming-kv-cache-eviction-under-fixed-budgets" tabindex="-1">Forget Without Compromise: Nexus Sampling for Streaming KV-Cache Eviction Under Fixed Budgets <a class="header-anchor" href="#forget-without-compromise-nexus-sampling-for-streaming-kv-cache-eviction-under-fixed-budgets" aria-label="Permalink to &quot;Forget Without Compromise: Nexus Sampling for Streaming KV-Cache Eviction Under Fixed Budgets&quot;">​</a></h1><p><strong>Authors</strong>: Duc Duong, Hoang Anh Duy Le, Jianwen Xie, Anshumali Shrivastava, Zhaozhuo Xu <strong>Published</strong>: June 22, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.23961" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.23961</a> · <a href="https://arxiv.org/html/2606.23961v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.23961 <strong>Categories</strong>: cs.LG, KV cache <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.23961" target="_blank" rel="noreferrer">research/papers/pdfs/2606.23961.pdf</a> (21 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-context and agentic LLM workloads push the KV cache past any fixed memory budget, forcing the inference stack to permanently evict tokens at every step of a continuous-inference stream. Existing methods all share the same template, a per-step direct-attention score followed by deterministic top-K selection, which converts a single below-cutoff step into an irreversible verdict and permanently erases any subtly important token that direct attention cannot single out from noise. To address this challenge, we propose Nexus Sampling, a training-free eviction method that pairs Nexus scoring, an iterative walk over direct attention that surfaces bridge tokens, with weighted reservoir sampling, which retains tokens with inclusion probability in place of deterministic top-K. Theoretically, we show that Nexus Sampling dominates deterministic top-K in long-run survival of subtly important tokens. Empirically, at 80% KV cache eviction, Nexus Sampling matches dense attention within 1% on LongBench while outperforming top-K baselines on retrieval-heavy tasks, with up to 10x smaller per-sequence cache memory.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>Nexus Sampling</strong>：training-free 的 streaming KV cache eviction 方法，解決現有 deterministic top-K 方案的「單步失分即永久刪除」缺陷。</li><li>引入 <strong>Nexus scoring</strong>：對 direct attention 做 iterative walk，挖掘 bridge token（連結性強但單步 attention 不突出的 token）。</li><li>以 <strong>weighted reservoir sampling</strong> 取代 deterministic top-K：token 以 inclusion probability 保留，避免單一低分步導致不可逆淘汰。</li><li>理論上證明 Nexus Sampling 在長期 token survival 上支配（dominates）deterministic top-K。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>80% KV cache eviction 條件下，LongBench 上與 dense attention 差距 <strong>&lt;1%</strong>。</li><li>retrieval-heavy tasks 上超越 top-K baselines。</li><li>per-sequence cache memory 可縮小 <strong>最高 10×</strong>。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未設獨立 Limitations 章節。</li><li>Nexus scoring 為 iterative walk，相較 direct attention 有額外計算開銷，論文未詳述延遲數字。</li><li>評測以 LongBench 為主，針對超長 context（&gt;1M token）或多模態場景的泛化能力尚未驗證。</li><li>目前為 inference-only 方法，與訓練期 context compression 技術的協同效果未探討。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management.md — NLAH 原則與 token budget</strong>：Nexus Sampling 的核心問題（固定 memory budget 下如何選擇保留哪些 token）直接對應 NLAH 原則中「Right context &gt; more context」的設計思路；bridge token 概念可類比於「高價值 context 放 HEAD/TAIL」的人工選擇策略。</li><li><strong>core.md — 不可逆決策閘門（APPLY gate）</strong>：論文批評 deterministic top-K 將「單步低分」轉為「不可逆淘汰」，與 The Loop 中「破壞性動作需二次確認、避免不可逆操作」的設計哲學對應；weighted sampling 引入的隨機性可視為一種 reversibility buffer。</li><li><strong><code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） — fan-out 與長 agentic workload</strong>：論文明確針對 agentic LLM workload 的 streaming KV cache 問題，與 workspace 中多 sub-agent 並行、長時任務的 context 管理需求高度相關；⚠️ 實際落地需推理框架（vLLM/SGLang 等）支援 custom eviction policy，workspace 目前無此基礎設施。</li><li><strong>unverified_success 閘門</strong>：論文的 empirical 結果均以 LongBench benchmark 為準，對應 TEST 階段「展示真實輸出而非口頭聲稱」；⚠️ 將此方法引入 production inference pipeline 前，需在實際 workload 上做獨立驗證，不得以 benchmark 數字直接視為 verified。</li></ul>',16)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
